/* UI structure only: the active provider is explicitly a browser-local demo. */
let authReturnTo='account', resetPreview=false;
const currentAccount=()=>accountService.getCurrentUser();
const isAdminPreview=()=>currentAccount()?.role==='admin';
const getGuestReceipts=()=>read('guest-receipts',[]);
function rememberGuestOrder(id){if(!currentAccount()){try{localStorage.setItem('abayat-guest-receipts',JSON.stringify([...new Set([...getGuestReceipts(),id])]))}catch{}}}
function orderIdentity(data){const user=currentAccount();return {customerId:user?.role==='client'?user.uid:null,customerType:user?.role==='client'?'account':'guest',email:(data.email||'').trim(),emailStatus:data.email?.trim()?'preview':'not-requested'}}
function canViewOrder(o){return !!o&&(isAdminPreview()||(currentAccount()?.role==='client'&&o.customerId===currentAccount().uid)||(!o.customerId&&getGuestReceipts().includes(o.id)))}
function customerOrders(){const user=currentAccount();return orders.filter(o=>user?.role==='client'?o.customerId===user.uid:!o.customerId&&getGuestReceipts().includes(o.id))}
function authNotice(){return `<p class="auth-demo">معاينة تفاعلية · استخدمي بيانات وهمية. كلمة المرور لا تُحفظ ولا يتم التحقق منها، ولا تُرسل رسائل فعلية.</p>`}
function passwordField(label,name='password',confirm=false){return `<label class="field">${label}<span class="password-control"><input name="${name}" type="password" required minlength="8" maxlength="128" autocomplete="${confirm?'new-password':'off'}" placeholder="٨ أحرف على الأقل"><button type="button" aria-label="إظهار ${label}" onclick="togglePassword(this)">إظهار</button></span></label>`}
function togglePassword(button){const input=button.previousElementSibling;input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'إظهار':'إخفاء';button.setAttribute('aria-label',(input.type==='password'?'إظهار ':'إخفاء ')+(input.name==='confirm'?'تأكيد كلمة المرور':'كلمة المرور'))}
function authShell(title,subtitle,body,notice=authNotice()){return `<section class="auth-layout"><div class="auth-story"><div class="eyebrow">YOUR EVERYDAY, ELEVATED</div><h2>تفاصيلك محفوظة.<br>واختياراتك أقرب.</h2><p>مساحة لكِ، لمتابعة طلباتك والعودة إلى القطع التي تحبينها.</p><div class="auth-image">${mediaImage('category-beige','تشكيلة عبايات')}</div><a href="#checkout" class="auth-guest-link">تفضّلين الطلب بدون حساب؟ تابعي كزائرة ←</a></div><div class="auth-content"><a href="#home" class="muted">الرئيسية / حسابي</a><h1>${title}</h1><p class="auth-subtitle">${subtitle}</p>${body}${notice}</div></section>`}
function signInPage(admin=false){return authShell('دخول تجريبي','أهلًا بعودتكِ، حسابك أقرب بضغطة.',`<form onsubmit="event.preventDefault();enterAccountPreview(this.elements.role.value)"><fieldset class="demo-role-switch"><legend class="sr-only">نوع الحساب</legend><label><input type="radio" name="role" value="client" checked><span>عميل</span></label><label><input type="radio" name="role" value="admin"><span>أدمن</span></label></fieldset><label class="field">اسم المستخدم أو البريد الإلكتروني<input name="username" type="text" autocomplete="username" placeholder="اسم المستخدم أو البريد الإلكتروني"></label><label class="field">كلمة المرور<span class="password-control"><input name="password" type="password" autocomplete="off" placeholder="كلمة المرور"><button type="button" aria-label="إظهار كلمة المرور" onclick="togglePassword(this)">إظهار</button></span></label><a href="#forgot-password" class="auth-forgot">نسيتِ كلمة المرور؟</a><button class="button full" type="submit">دخول تجريبي</button></form><p class="auth-switch">ليس لديكِ حساب؟ <a href="#signup">إنشاء حساب</a></p>`,`<p class="auth-demo">نسخة تجريبية · يمكنك الدخول بدون تعبئة البيانات. كلمة المرور لا تُحفظ ولا يتم التحقق منها.</p>`)}
function signUpPage(){return authShell('مساحتكِ تبدأ هنا','حساب اختياري لتجربة تسوّق أكثر سهولة.',`<form onsubmit="submitAccount(event,'signup')"><label class="field">الاسم الكامل<input name="name" required minlength="2" maxlength="70" autocomplete="name" placeholder="اسمكِ الكريم"></label><label class="field">البريد الإلكتروني<input name="email" type="email" required dir="ltr" autocomplete="email" placeholder="name@example.com"></label>${passwordField('كلمة المرور')}${passwordField('تأكيد كلمة المرور','confirm',true)}<p class="form-error" role="alert"></p><button class="button full">إنشاء حساب تجريبي</button></form><p class="auth-switch">لديكِ حساب بالفعل؟ <a href="#signin">تسجيل الدخول</a></p><a class="auth-guest-link" href="#checkout">متابعة الطلب بدون حساب ←</a>`)}
function forgotPage(){return authShell('نسيتِ كلمة المرور؟','أدخلي بريدك لمعاينة خطوات استعادة حسابك.',`<form onsubmit="submitAccount(event,'forgot')"><label class="field">البريد الإلكتروني<input name="email" type="email" required dir="ltr" autocomplete="email" placeholder="name@example.com"></label><p class="form-error" role="alert"></p><button class="button full">معاينة استعادة كلمة المرور</button></form><p class="auth-switch"><a href="#signin">العودة لتسجيل الدخول</a></p>`)}
function resetPage(){if(!resetPreview)return authShell('رابط غير متاح','ابدئي من صفحة استعادة كلمة المرور.',`<a href="#forgot-password" class="button full">استعادة كلمة المرور</a>`);return authShell('كلمة مرور جديدة','معاينة الخطوة التي تُفتح من رابط البريد بعد تفعيل الخدمة.',`<form onsubmit="submitAccount(event,'reset')">${passwordField('كلمة المرور الجديدة')}${passwordField('تأكيد كلمة المرور','confirm',true)}<p class="form-error" role="alert"></p><button class="button full">معاينة حفظ كلمة المرور</button></form>`)}
function afterAccountLogin(){const user=currentAccount();location.hash=user.role==='admin'?'admin':authReturnTo==='checkout'?'checkout':'account';render()}
async function submitAccount(event,action){event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form)),error=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"],button.button');error.textContent='';if((action==='signup'||action==='reset')&&data.password!==data.confirm){error.textContent='كلمتا المرور غير متطابقتين.';return}button.disabled=true;try{
 if(action==='signin'){await accountService.signIn(data);form.reset();afterAccountLogin()}
 if(action==='signup'){await accountService.signUp(data);form.reset();afterAccountLogin()}
 if(action==='forgot'){await accountService.requestPasswordReset(data.email);resetPreview=true;modal(`<div class="auth-message"><span class="check">✉</span><h2>هذه معاينة لرسالة الاستعادة</h2><p>لم يُرسل أي بريد. بعد الربط، سيصل رابط آمن إذا كان الحساب موجودًا.</p><button class="button" onclick="$('#modal').close();location.hash='reset-password'">معاينة تعيين كلمة مرور جديدة</button></div>`)}
 if(action==='reset'){await accountService.confirmPasswordReset(data);form.reset();resetPreview=false;location.hash='signin';toast('اكتملت المعاينة. لم تتغير كلمة مرور فعلية.')}
 }catch(e){error.textContent=e.message}finally{button.disabled=false}}
async function enterAccountPreview(role){try{await accountService.enterPreview(role);afterAccountLogin()}catch(e){toast(e.message)}}
async function signOutAccount(){await accountService.signOut();$('#modal')?.close();authReturnTo='account';location.hash='home';render();toast('تم الخروج من حساب العرض')}
function accountPage(){const user=currentAccount();if(!user)return signInPage();const list=customerOrders();return `<section class="section account-section"><div class="account-heading"><div><span class="eyebrow">MY ACCOUNT</span><h1>أهلًا ${esc(user.name)}</h1><p class="muted">${user.role==='admin'?'حساب إدارة تجريبي':'طلباتك وتفاصيلك، في مكان واحد.'}</p></div><button class="button outline" onclick="signOutAccount()">تسجيل الخروج</button></div><div class="account-grid"><aside class="panel account-menu"><span class="account-avatar">${esc(user.name[0])}</span><h3>${esc(user.name)}</h3><p dir="ltr">${esc(user.email)}</p><span class="small-chip">${user.role==='admin'?'أدمن · معاينة':'عميل · معاينة'}</span><a href="#orders">طلباتي <span>${list.length}</span></a><a href="#favorites">المفضلة</a>${user.role==='admin'?'<a href="#admin">لوحة الإدارة ←</a>':''}</aside><div><form class="panel" onsubmit="updateAccountProfile(event)"><h2>بيانات الحساب</h2><label class="field">الاسم الكامل<input name="name" value="${esc(user.name)}" required minlength="2" maxlength="70"></label><label class="field">البريد الإلكتروني<input value="${esc(user.email)}" type="email" disabled dir="ltr"></label><label class="field">رقم الجوال<input name="phone" value="${esc(user.phone)}" type="tel" dir="ltr" maxlength="20"></label><p class="form-error" role="alert"></p><button class="button">حفظ بيانات العرض</button><a href="#forgot-password" class="account-reset">تغيير كلمة المرور</a></form><div class="panel account-summary"><h2>آخر الطلبات</h2>${list.length?list.slice(0,3).map(o=>`<a class="row" href="#success/${o.id}"><span dir="ltr">${esc(o.id)}</span><span>${esc(o.status)}</span><b>${money(o.total)}</b></a>`).join(''):'<p class="muted">لم تضيفي أي طلب لهذا الحساب بعد.</p>'}<a href="#shop" class="text-button">اكتشفي التشكيلة ←</a></div></div></div>${authNotice()}</section>`}
async function updateAccountProfile(e){e.preventDefault();try{await accountService.updateProfile(Object.fromEntries(new FormData(e.target)));render(false);toast('تم حفظ بيانات العرض')}catch(error){e.target.querySelector('.form-error').textContent=error.message}}
function clientOrdersPage(){const user=currentAccount(),list=customerOrders(),paged=paginate(list,'client-orders',20);return `<section class="section"><div class="section-head"><h2>${user?.role==='client'?'طلباتي':'طلبات الزائر على هذا المتصفح'}</h2><a href="#${user?'account':'signin'}">${user?'حسابي':'تسجيل الدخول اختياري'}</a></div><p class="muted">${user?'تظهر هنا الطلبات التي أنشأتِها بهذا الحساب التجريبي.':'لا تحتاجين حسابًا لإتمام طلبك. احتفظي برقم الطلب، والطلبات التجريبية هنا محفوظة على هذا المتصفح فقط.'}</p>${list.length?`<div class="table-wrap"><table><thead><tr><th>رقم الطلب</th><th>الحالة</th><th>الإجمالي</th><th>التفاصيل</th></tr></thead><tbody>${paged.items.map(o=>`<tr><td dir="ltr">${esc(o.id)}</td><td>${esc(o.status)}</td><td>${money(o.total)}</td><td><button class="text-button" onclick="showOrder('${o.id}')">عرض الطلب</button></td></tr>`).join('')}</tbody></table></div>${paged.controls}`:'<div class="empty"><h3>لا توجد طلبات حتى الآن</h3><a href="#shop" class="button">تسوقي التشكيلة</a></div>'}</section>`}
function clientsAdminPage(){const list=accountService.listProfiles().filter(p=>[p.name,p.email,p.role==='admin'?'أدمن':'عميل'].some(v=>v.includes(adminQuery))),paged=paginate(list,'clients',20);return `<div class="page-title"><div><h1>العملاء والحسابات</h1><p>حسابات العرض منفصلة عن طلبات الزوار.</p></div><span class="small-chip">${list.length} حساب</span></div><div class="demo-note">معاينة الصلاحيات فقط. التسجيل ينشئ عميلًا؛ صلاحية الأدمن الحقيقية تُمنح من الخادم عند الربط.</div><div class="dashboard-panel account-summary"><div class="table-wrap"><table><thead><tr><th>الاسم</th><th>البريد</th><th>نوع الحساب</th><th>عدد الطلبات</th></tr></thead><tbody>${paged.items.map(p=>`<tr><td>${esc(p.name)}</td><td dir="ltr">${esc(p.email)}</td><td><span class="status">${p.role==='admin'?'أدمن':'عميل'}</span></td><td>${orders.filter(o=>o.customerId===p.uid).length}</td></tr>`).join('')}</tbody></table>${!list.length?'<div class="empty">لا توجد حسابات مطابقة.</div>':''}</div>${paged.controls}</div><div class="panel"><h2>الطلب كزائر متاح دائمًا</h2><p>عدد طلبات الزوار: <b>${orders.filter(o=>!o.sample&&!o.customerId).length}</b></p><a href="#admin/orders" class="text-button">عرض الطلبات ←</a></div>`}
function previewOrderEmail(id){const o=orders.find(o=>o.id===id);if(!canViewOrder(o)||!o.email)return;modal(`<div class="email-preview"><span class="small-chip">معاينة فقط · لم تُرسل</span><p class="muted">إلى: <span dir="ltr">${esc(o.email)}</span></p><h2>${esc(settings.name)}</h2><h3>استلمنا طلبك، شكرًا لثقتك</h3><p>أهلًا ${esc(o.name)}، طلبك <b dir="ltr">${esc(o.id)}</b> قيد المراجعة.</p>${o.items.map(x=>`<div class="row"><span>${esc(x.name)} · ${esc(x.size)} × ${x.qty}</span><b>${money(x.price*x.qty)}</b></div>`).join('')}<hr><div class="row"><b>الإجمالي شامل التوصيل</b><b>${money(o.total)}</b></div><p>الدفع عند الاستلام</p><p class="muted">بعد الربط، تُرسل رسالة التأكيد عند حفظ الطلب بنجاح.</p></div>`)}
const storeCheckout=checkout;
checkout=function(){let html=storeCheckout();if(!cart.length)return html;const u=currentAccount();return html.replace('<h2>معلومات التوصيل</h2>',`<h2>معلومات التوصيل</h2><div class="checkout-account">${u?`تُكملين الطلب باسم <strong>${esc(u.name)}</strong> · <a href="#account">حسابي</a>`:'<strong>أكملي طلبك كزائرة</strong><span>بدون تسجيل أو إنشاء حساب.</span><a href="#signin" onclick="authReturnTo=\'checkout\'">عندكِ حساب؟ تسجيل الدخول اختياري</a>'}</div>`).replace('name="name" required','name="name" value="'+esc(u?.name||'')+'" required').replace('name="phone" type="tel"','name="phone" value="'+esc(u?.phone||'')+'" type="tel"').replace('<h3>طريقة الدفع</h3>',`<label class="field">البريد الإلكتروني <span class="muted">اختياري لتأكيد الطلب، بدون إنشاء حساب</span><input name="email" type="email" dir="ltr" value="${esc(u?.email||'')}" placeholder="name@example.com"><small class="muted">في الديمو تظهر معاينة الرسالة فقط؛ الإرسال يُفعّل بعد الربط.</small></label><h3>طريقة الدفع</h3>`)};
const storeSuccess=success;
success=function(id){const o=orders.find(o=>o.id===id);if(!canViewOrder(o))return '<div class="empty"><h2>الطلب غير متاح في هذه الجلسة</h2><a href="#orders" class="button">طلباتي</a></div>';return storeSuccess(id).replace('<a class="button outline" href="#admin/orders">تجربة إدارة الطلب</a>',`<a class="button outline" href="#orders">متابعة طلباتي</a>${o.email?`<div class="order-email-note"><p>رسالة تأكيد الطلب جاهزة للمعاينة · لم يتم إرسالها.</p><button class="button outline" onclick="previewOrderEmail('${o.id}')">معاينة إيميل تأكيد الطلب</button></div>`:'<p class="muted">أتممتِ الطلب بدون بريد إلكتروني. احتفظي برقم الطلب لمتابعته.</p>'}`)};
const storeShowOrder=showOrder;
showOrder=function(id){if(!canViewOrder(orders.find(o=>o.id===id))){toast('الطلب غير متاح لهذا الحساب');return}storeShowOrder(id)};
const storeAdmin=admin;
admin=function(tab){if(!isAdminPreview())return signInPage(true);return storeAdmin(tab)};
const storeRender=render;
render=function(scroll=true){let page=location.hash.slice(1).split('/')[0];const routes={signin:()=>signInPage(),'admin-login':()=>signInPage(true),signup:signUpPage,'forgot-password':forgotPage,'reset-password':resetPage,account:accountPage,orders:clientOrdersPage};if(routes[page]){document.body.classList.remove('admin-mode');$('#app').innerHTML=routes[page]();updateCartCount();if(scroll)window.scrollTo(0,0)}else{storeRender(scroll);if(page==='admin'&&!isAdminPreview())document.body.classList.remove('admin-mode')}document.querySelectorAll('[data-admin-only]').forEach(link=>{link.hidden=!isAdminPreview()});const link=$('#account-link');if(link){link.href=currentAccount()?'#account':'#signin';link.textContent=currentAccount()?'حسابي':'دخول / تسجيل'}if(currentAccount()&&page!=='admin-login'&&page!=='signin')authReturnTo='account';};
